	@Test
	void graphScopesGroupingAndNestedExpressionsMatchEveryBinding() {
		String channels = "(COUNT(*) AS ?n) (COUNT(DISTINCT ?s) AS ?sCount) "
				+ "(COUNT(DISTINCT ?o) AS ?oCount) (SUM(IF(isLiteral(?o), 2, -1)) AS ?sum) ";
		for (String query : List.of(
				"SELECT ?g " + channels + "WHERE { GRAPH ?g { ?s ?p ?o } } GROUP BY ?g",
				"SELECT ?p " + channels + "WHERE { GRAPH ?g { ?s ?p ?o } } GROUP BY ?p",
				"SELECT ?g ?p " + channels + "WHERE { GRAPH ?g { ?s ?p ?o } } GROUP BY ?g ?p",
				"SELECT ?s " + channels + "WHERE { GRAPH ?g { ?s ?p ?o } } GROUP BY ?s",
				"SELECT " + channels + "WHERE { ?s ?p ?o }",
				"SELECT " + channels + "FROM <urn:census:g1> FROM <urn:census:g2> WHERE { ?s ?p ?o }",
				"SELECT " + channels + "FROM NAMED <urn:census:g1> WHERE { GRAPH ?g { ?s ?p ?o } }",
				CENSUS.replace("GRAPH ?g", "GRAPH <urn:census:g1>").replace("COUNT(DISTINCT ?g)", "COUNT(*)"),
				CENSUS.replace("?s ?p ?o", "?s <urn:census:p1> ?o").replace("COUNT(DISTINCT ?p)", "COUNT(*)"),
				CENSUS.replace("?s ?p ?o", "<urn:census:s1> ?p ?o")
						.replace("COUNT(DISTINCT ?s)", "COUNT(*)")
						.replace("isBlank(?s)", "isBlank(<urn:census:s1>)"),
				CENSUS.replace("?s ?p ?o", "?s ?p <urn:census:o1>").replace("?o)", "<urn:census:o1>)"),
				"SELECT ?g " + channels + "WHERE { GRAPH ?g { ?s ?p ?o } } GROUP BY ?g HAVING(COUNT(*) > 1)",
				"SELECT ?sum WHERE { { SELECT " + channels + "WHERE { GRAPH ?g { ?s ?p ?o } } } FILTER(?sum < 1) }",
				"SELECT (SUM(?n) AS ?total) (COUNT(DISTINCT ?n) AS ?kinds) (SUM(DISTINCT ?n) AS ?distinctSum) "
						+ "WHERE { GRAPH ?g { ?s ?p ?o } BIND(?o AS ?value) BIND(isLiteral(?value) AS ?literal) "
						+ "BIND(IF(?literal, 9223372036854775808, IF(isIRI(?value) || isBlank(?value), -4, 7)) AS ?n) }",
				"SELECT (SUM(IF(IF(isIRI(?o), true, isBlank(?o)), 3, 5)) AS ?sum) "
						+ "WHERE { GRAPH ?g { ?s ?p ?o } FILTER(isIRI(?s) && !isLiteral(?s)) }",
				"SELECT (SUM(IF(isTriple(?o), 3, 0)) AS ?sum) WHERE { GRAPH ?g { ?s ?p ?o } }")) {
			assertParity(query);
		}
	}

	@Test
	void unsupportedInteriorsRetainOrdinarySemantics() {
		for (String query : List.of(
				"SELECT (SUM(IF(isIRI(?o), 1.5, 2.5)) AS ?n) WHERE { GRAPH ?g { ?s ?p ?o } }",
				"SELECT (SUM(?missing) AS ?n) WHERE { GRAPH ?g { ?s ?p ?o } }",
				"SELECT (SUM(?n) AS ?total) WHERE { GRAPH ?g { ?s ?p ?o } BIND(IF(isIRI(?later), 1, 0) AS ?n) "
						+ "BIND(?o AS ?later) }",
				"SELECT (SUM(?n) AS ?total) WHERE { GRAPH ?g { ?s ?p ?o } BIND(IF(isIRI(?n), 1, 0) AS ?n) }",
				"SELECT (SUM(IF(isIRI(?o), 1, 0)) AS ?n) WHERE { { GRAPH ?g { ?s ?p ?o } } UNION { ?s ?p ?o } }",
				"SELECT (SUM(IF(isIRI(?o), 1, 0)) AS ?n) WHERE { GRAPH ?g { ?s ?p ?o } "
						+ "OPTIONAL { ?s <urn:census:absent> ?x } }",
				"SELECT (SUM(IF(isIRI(?o), 1, 0)) AS ?n) WHERE { GRAPH ?g { ?s ?p ?o } FILTER(RAND() < 2) }")) {
			assertParity(query);
		}
	}

	@Test
	void populatedGraphsAndVisibilityFollowTheCurrentSnapshot() {
		try (SailRepositoryConnection reader = repository.getConnection();
				SailRepositoryConnection writer = repository.getConnection()) {
			reader.begin(IsolationLevels.SNAPSHOT);
			List<BindingSet> old = rows(reader, CENSUS);
			ValueFactory vf = writer.getValueFactory();
			IRI g2 = vf.createIRI(EX + "g2");
			writer.begin();
			writer.clear(g2);
			writer.add(vf.createIRI(EX + "new"), vf.createIRI(EX + "p3"), vf.createLiteral("new"),
					vf.createIRI(EX + "g3"));
			assertParity(writer, CENSUS);
			writer.rollback();
			assertThat(rows(writer, CENSUS)).containsExactlyElementsOf(old);
			writer.begin();
			writer.clear(g2);
			writer.commit();
			assertThat(rows(reader, CENSUS)).containsExactlyElementsOf(old);
			assertParity(writer, CENSUS);
			assertThat(((Literal) rows(writer, CENSUS).get(0).getValue("namedGraphs")).longValue()).isEqualTo(1);
			reader.commit();
		}
		assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
		assertParity(CENSUS);
		repository.shutDown();
		store = new LmdbStore(dataDir,
				new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true)
						.setDirectAdjacencyEnabled(true));
		repository = new SailRepository(store);
		repository.init();
		assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
		assertParity(CENSUS);
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.clear();
		}
		assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
		assertParity(CENSUS);
		assertThat(rows(CENSUS).get(0))
				.allSatisfy(binding -> assertThat(((Literal) binding.getValue()).longValue()).isZero());
		assertParity("SELECT ?g (COUNT(*) AS ?n) (SUM(IF(isIRI(?o), 1, 0)) AS ?sum) "
				+ "WHERE { GRAPH ?g { ?s ?p ?o } } GROUP BY ?g");
	}

	@Test
	void homogeneousPagesUseCountsAndUnavailableProjectionsUseExactDomains() {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			connection.begin();
			connection.clear();
			IRI p = vf.createIRI(EX + "p");
			IRI g = vf.createIRI(EX + "g");
			for (int i = 0; i < 12_000; i++) {
				// Overlapping subject/object domains cannot be summed over predicates.
				connection.add(vf.createIRI(EX + i), p, vf.createIRI(EX + (i + 1)), g);
				connection.add(vf.createIRI(EX + i), vf.createIRI(EX + "p2"), vf.createIRI(EX + (i + 1)), g);
			}
			connection.commit();
		}
		assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
		assertParity(CENSUS);
		String metadata = telemetry(CENSUS);
		assertThat(metadata).contains("nativeExecutionPath=adjacencyCensus", "decoded=root:0,neighbor:0,context:0");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			connection.begin();
			connection.add(vf.createIRI(EX + "0"), vf.createIRI(EX + "p"), vf.createIRI(EX + "1"));
			connection.add(vf.createIRI(EX + "defaultOnly"), vf.createIRI(EX + "p"), vf.createLiteral("defaultOnly"));
			connection.commit();
		}
		assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
		assertParity(CENSUS);
		String corrected = telemetry(CENSUS);
		var decodes = Pattern.compile("decoded=root:(\\d+),neighbor:(\\d+),context:(\\d+)")
				.matcher(corrected);
		assertThat(decodes.find()).isTrue();
		assertThat(Long.parseLong(decodes.group(2))).as("only excluded or mixed pages need neighbor decoding")
				.isLessThan(2_000L);
		System.setProperty(AdjacencyEngagementTestAccess.NODE_PREDICATE_SERVE_PROPERTY, "false");
		assertParity(CENSUS);
		assertThat(telemetry(CENSUS)).contains("nativeExecutionPath=adjacencyCensus")
				.doesNotContain("decoded=root:0,neighbor:0,context:0");
	}

